SELECT min(accepted_lease_until)
FROM assistant_delivery.assistant_test_run
WHERE tenant_id = #{tenantId}
  AND status = 'RUNNING'
  AND accepted_lease_until > #{acceptedAt}

mapper.update:
UPDATE assistant_delivery.assistant_test_run
SET status = #{status},
    refusal_reason = #{refusalReason},
    input_tokens = #{inputTokens},
    output_tokens = #{outputTokens},
    total_tokens = #{totalTokens},
    version = #{newVersion},
    completed_at = #{completedAt}
WHERE tenant_id = #{tenantId}
  AND id = #{runId}
  AND status = 'RUNNING'
  AND version = #{expectedVersion}
